// Server-only. Loads the devnet test wallet keypairs (owner-a, owner-b,
// vault) used by /api/devnet/transfer's dev-only server-signing shortcut
// (see that route's comments and AGENTS.md section 3). Keys live outside
// the repo, same default as scripts/solana/src/config.ts
// (~/.config/twinfold/devnet/), generated by
// `cd scripts/solana && npm run wallets:generate`. Never import this from a
// client component; never log the returned Keypair's secret key.

import * as fs from "node:fs";
import * as os from "node:os";
import * as path from "node:path";
import { Keypair } from "@solana/web3.js";

// "escrow" is Twinfold's redemption escrow wallet (redeem dry run): the owner moves a locked Asset here and it
// is burned (or returned on cancel) from here, always with the vault as fee payer. It is never accepted by
// the dev server-signing shortcut (/api/devnet/transfer): normalizeDevnetWalletLabel does not return it.
export type DevnetWalletLabel = "owner-a" | "owner-b" | "vault" | "escrow";

const KEY_DIR =
  process.env.TWINFOLD_DEVNET_KEY_DIR ?? path.join(os.homedir(), ".config", "twinfold", "devnet");

function keypairPath(label: DevnetWalletLabel): string {
  return path.join(KEY_DIR, `${label}.json`);
}

export function loadDevnetKeypair(label: DevnetWalletLabel): Keypair {
  const filePath = keypairPath(label);
  if (!fs.existsSync(filePath)) {
    throw new Error(
      `Devnet keypair not found for "${label}" at ${filePath}. ` +
        `Run "cd scripts/solana && npm run wallets:generate" first.`
    );
  }
  const secret = Uint8Array.from(JSON.parse(fs.readFileSync(filePath, "utf8")));
  return Keypair.fromSecretKey(secret);
}

export function normalizeDevnetWalletLabel(raw: string): DevnetWalletLabel {
  const value = raw.trim().toLowerCase();
  if (value === "owner-a" || value === "a") return "owner-a";
  if (value === "owner-b" || value === "b") return "owner-b";
  if (value === "vault") return "vault";
  throw new Error(`Unknown devnet wallet label "${raw}". Use "owner-a", "owner-b", or "vault".`);
}
